{"code":"import json, collections, itertools
with open('table.json') as f: table=json.load(f)
freq=collections.Counter(table.values())
freq_order=sorted(set(freq.values()), reverse=True)
groups={i:sorted([s for s,c in freq.items() if c==fr]) for i,fr in enumerate(freq_order)}
group_of={s:i for i,sy in groups.items() for s in sy}
syms=sorted(sum(groups.values(), []))
sym_idx={s:i for i,s in enumerate(syms)}
triples=[(a,b,c) for a in range(5) for b in range(5) for c in range(5)]
tri_idx={t:25+i for i,t in enumerate(triples)}
rows=[]
for key,out in table.items():
    x,y,z=key
    t=(group_of[x],group_of[y],group_of[z])
    row=[0]*150
    row[sym_idx[out]]=1
    row[sym_idx[x]]=(row[sym_idx[x]]-1)%5
    row[sym_idx[y]]=(row[sym_idx[y]]-2)%5
    row[sym_idx[z]]=(row[sym_idx[z]]-3)%5
    row[tri_idx[t]]=(row[tri_idx[t]]-1)%5
    rows.append(row)
# rref
A=[r[:] for r in rows]
m=len(A); n=150
rank=0; piv=[]
inv={1:1,2:3,3:2,4:4}
for col in range(n):
    pivot=None
    for i in range(rank,m):
        if A[i][col]%5:
            pivot=i; break
    if pivot is None: continue
    A[rank],A[pivot]=A[pivot],A[rank]
    fac=inv[A[rank][col]%5]
    A[rank]=[(v*fac)%5 for v in A[rank]]
    for i in range(m):
        if i!=rank and A[i][col]%5:
            f=A[i][col]%5
            A[i]=[(A[i][j]-f*A[rank][j])%5 for j in range(n)]
    piv.append(col)
    rank+=1
free=[c for c in range(n) if c not in piv]
basis=[]
for fv in free:
    vec=[0]*n; vec[fv]=1
    for r in range(rank-1,-1,-1):
        pc=piv[r]
        s=sum(A[r][j]*vec[j] for j in free)%5
        vec[pc]=(-s)%5
    basis.append(vec)
# search combinations for symbol labels having each group be permutation of 0..4
sols=[]
for coeffs in itertools.product(range(5), repeat=len(basis)):
    if all(c==0 for c in coeffs):
        continue
    vals=[sum(coeffs[k]*basis[k][i] for k in range(len(basis)))%5 for i in range(n)]
    ok=True
    for g in range(5):
        lab=[vals[sym_idx[s]] for s in groups[g]]
        if set(lab)!=set(range(5)):
            ok=False; break
    if ok:
        sols.append((coeffs, vals))
print('num good', len(sols))
for coeffs,vals in sols[:20]:
    print('coeffs',coeffs)
    for g in range(5):
        print(g, groups[g], [vals[sym_idx[s]] for s in groups[g]])
    # show c_t sample
    cvals={t:vals[tri_idx[t]] for t in triples}
    print('c000,c012,c444', cvals[(0,0,0)], cvals[(0,1,2)], cvals[(4,4,4)])
    break
"}

